const crypto = require('crypto');

function hashPassword(password, salt) {
  return crypto.createHash('sha256').update(salt + password).digest('hex');
}

function generateSalt() {
  return crypto.randomBytes(16).toString('hex');
}

function generateToken() {
  return crypto.randomUUID();
}

function tokenExpires(hours = 24) {
  return new Date(Date.now() + hours * 3600000).toISOString();
}

function isExpired(isoDate) {
  if (!isoDate) return true;
  return new Date(isoDate) < new Date();
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function isValidTime(time) {
  return /^([01]?\d|2[0-3]):[0-5]\d$/.test(time);
}

function isValidUsername(name) {
  return /^[a-zA-Z0-9_]{3,20}$/.test(name);
}

function isStrongPassword(pwd) {
  return pwd.length >= 8 && /[A-Za-z]/.test(pwd) && /\d/.test(pwd);
}


const trigger = $('When Executed by Another Workflow').first().json;
const token = trigger.sessionToken || '';
const rows = $input.all().map(i => i.json);
const user = rows.find(r => r.session_token === token);

if (!user) {
  return { json: { valid: false, error: 'Session invalide.' } };
}
if (isExpired(user.session_expires_at)) {
  return { json: { valid: false, error: 'Session expirée. Reconnecte-toi.' } };
}

return {
  json: {
    valid: true,
    userId: user.id,
    username: user.username,
    email: user.email,
    interests: user.interests,
    schedule_time: user.schedule_time,
    active: user.active,
    created_at: user.created_at,
    gdpr_consent_at: user.gdpr_consent_at
  }
};
